import { cva, type VariantProps } from "class-variance-authority"
import type * as React from "react"
import { cn } from "@/lib/utils"

import "@/styles/feedback.styles.css"

const alertVariants = cva("alert-layout", {
  defaultVariants: {
    variant: "default",
  },
  variants: {
    variant: {
      default: "",
      destructive: "alert-destructive-layout",
      info: "alert-info-layout",
      success: "alert-success-layout",
      warning: "alert-warning-layout",
    },
  },
})

export function Alert({
  className,
  variant,
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof alertVariants>): React.ReactElement {
  return (
    <div
      className={cn(alertVariants({ variant }), className)}
      data-slot="alert"
      role="alert"
      {...props}
    />
  )
}

export function AlertTitle({
  className,
  ...props
}: React.ComponentProps<"div">): React.ReactElement {
  return <div className={cn("alert-title-layout", className)} data-slot="alert-title" {...props} />
}

export function AlertDescription({
  className,
  ...props
}: React.ComponentProps<"div">): React.ReactElement {
  return (
    <div
      className={cn("alert-description-layout", className)}
      data-slot="alert-description"
      {...props}
    />
  )
}

export function AlertAction({
  className,
  ...props
}: React.ComponentProps<"div">): React.ReactElement {
  return (
    <div className={cn("alert-action-layout", className)} data-slot="alert-action" {...props} />
  )
}

/* Feedback anatomy. Status colors come from the consumer's existing theme. */
@layer components {
  .alert-layout {
    --alert-status: var(--border);
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: start;
    gap: calc(4 * var(--component-unit, 0.0625rem)) calc(12 * var(--component-unit, 0.0625rem));
    position: relative;
    width: 100%;
    border: 1px solid var(--alert-status);
    border-radius: var(--radius, 0.625rem);
    padding: calc(16 * var(--component-unit, 0.0625rem));
    background: var(--card);
    color: var(--card-foreground);
    font-size: calc(14 * var(--component-unit, 0.0625rem));
    line-height: calc(20 * var(--component-unit, 0.0625rem));
  }
  .alert-layout:has(> svg) {
    grid-template-columns: calc(16 * var(--component-unit, 0.0625rem)) minmax(0, 1fr) auto;
  }
  .alert-layout > svg {
    grid-column: 1;
    grid-row: 1 / 3;
    width: calc(16 * var(--component-unit, 0.0625rem));
    height: calc(20 * var(--component-unit, 0.0625rem));
    color: var(--muted-foreground);
  }
  .alert-layout:is(
    .alert-destructive-layout,
    .alert-info-layout,
    .alert-success-layout,
    .alert-warning-layout
  ) {
    border-color: color-mix(in srgb, var(--alert-status) 35%, var(--border));
  }
  .alert-layout:is(
      .alert-destructive-layout,
      .alert-info-layout,
      .alert-success-layout,
      .alert-warning-layout
    )
    > svg {
    color: var(--alert-status);
  }
  .alert-destructive-layout {
    --alert-status: var(--destructive);
  }
  .alert-info-layout {
    --alert-status: var(--info);
  }
  .alert-success-layout {
    --alert-status: var(--success);
  }
  .alert-warning-layout {
    --alert-status: var(--warning);
  }
  .alert-title-layout,
  .alert-description-layout {
    grid-column: 1;
    min-width: 0;
    overflow-wrap: anywhere;
  }
  .alert-layout:has(> svg) > :is(.alert-title-layout, .alert-description-layout) {
    grid-column: 2;
  }
  .alert-title-layout {
    font-weight: 600;
  }
  .alert-description-layout {
    display: flex;
    flex-direction: column;
    gap: calc(8 * var(--component-unit, 0.0625rem));
    color: var(--muted-foreground);
  }
  .alert-action-layout {
    display: flex;
    flex-wrap: wrap;
    gap: calc(8 * var(--component-unit, 0.0625rem));
    grid-column: -2;
    grid-row: 1 / 3;
    align-self: center;
  }
  .toast-viewport-layout {
    width: min(calc(384 * var(--component-unit, 0.0625rem)), calc(100vw - 32px));
    max-width: calc(100vw - 32px);
  }
  .toast-root-layout {
    padding: calc(16 * var(--component-unit, 0.0625rem));
    border-radius: var(--radius, 0.625rem);
    box-shadow: 0 6px 18px rgb(0 0 0 / 0.12);
  }
  .dark .toast-root-layout {
    box-shadow: 0 6px 18px rgb(0 0 0 / 0.2);
  }
  .toast-title-layout,
  .toast-description-layout {
    font-size: calc(14 * var(--component-unit, 0.0625rem));
    line-height: calc(20 * var(--component-unit, 0.0625rem));
    overflow-wrap: anywhere;
  }
  .toast-title-layout {
    font-weight: 600;
  }
  .toast-description-layout {
    color: var(--muted-foreground);
  }
  .toast-action-layout,
  .toast-close-layout {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    border-radius: max(0px, calc(var(--radius, 0.625rem) - 4px));
    outline: none;
    transition:
      background-color 100ms,
      color 100ms;
  }
  .toast-action-layout {
    min-height: calc(32 * var(--component-unit, 0.0625rem));
    padding: calc(4 * var(--component-unit, 0.0625rem)) calc(12 * var(--component-unit, 0.0625rem));
    border: 1px solid var(--input);
    background: transparent;
    color: var(--foreground);
    font-size: calc(14 * var(--component-unit, 0.0625rem));
    line-height: calc(20 * var(--component-unit, 0.0625rem));
    font-weight: 500;
  }
  .toast-close-layout {
    position: absolute;
    inset-block-start: calc(8 * var(--component-unit, 0.0625rem));
    inset-inline-end: calc(8 * var(--component-unit, 0.0625rem));
    width: calc(28 * var(--component-unit, 0.0625rem));
    height: calc(28 * var(--component-unit, 0.0625rem));
    color: var(--muted-foreground);
  }
  .toast-action-layout:focus-visible,
  .toast-close-layout:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
    box-shadow: none;
  }
  .toast-action-layout:disabled,
  .toast-close-layout:disabled {
    color: var(--muted-foreground);
    cursor: not-allowed;
  }
  .progress-layout {
    display: flex;
    flex-wrap: wrap;
    gap: calc(8 * var(--component-unit, 0.0625rem));
  }
  .progress-track-layout {
    position: relative;
    display: flex;
    align-items: center;
    width: 100%;
    height: calc(4 * var(--component-unit, 0.0625rem));
    overflow: hidden;
    border-radius: 999px;
    background: var(--muted);
  }
  .progress-indicator-layout {
    height: 100%;
    background: var(--primary);
    transition: width 160ms ease-out;
  }
  .progress-indicator-layout[data-indeterminate] {
    width: 40%;
    animation: feedback-progress 1.4s ease-in-out infinite;
  }
  .progress-label-layout,
  .progress-value-layout {
    font-size: calc(14 * var(--component-unit, 0.0625rem));
    line-height: calc(20 * var(--component-unit, 0.0625rem));
  }
  .progress-label-layout {
    font-weight: 500;
  }
  .progress-value-layout {
    margin-inline-start: auto;
    color: var(--muted-foreground);
    font-variant-numeric: tabular-nums;
  }
  @media (hover: hover) {
    .toast-action-layout:not(:disabled):hover,
    .toast-close-layout:not(:disabled):hover {
      background: var(--muted);
      color: var(--foreground);
    }
  }
  @media (max-width: 639px) {
    .alert-action-layout {
      grid-column: 1 / -1;
      grid-row: auto;
      margin-block-start: calc(8 * var(--component-unit, 0.0625rem));
    }
    .alert-layout:has(> svg) > .alert-action-layout {
      grid-column: 2 / -1;
    }
  }
  @media (pointer: coarse) {
    .toast-action-layout,
    .toast-close-layout {
      min-width: 44px;
      min-height: 44px;
    }
    .toast-root-layout {
      padding-inline-end: 28px;
    }
  }
  @media (prefers-reduced-motion: reduce) {
    .toast-root-layout,
    .toast-action-layout,
    .toast-close-layout,
    .progress-indicator-layout {
      transition: none;
    }
    .progress-indicator-layout[data-indeterminate] {
      animation: none;
    }
  }
  @media (forced-colors: active) {
    .alert-layout {
      border-color: CanvasText;
    }
    .toast-action-layout:focus-visible,
    .toast-close-layout:focus-visible {
      outline-color: Highlight;
    }
    .progress-track-layout {
      border: 1px solid CanvasText;
    }
    .progress-indicator-layout {
      background: Highlight;
    }
  }
}
@keyframes feedback-progress {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(350%);
  }
}
